1	import rows from "./prices.json";
2	
3	// Prices are USD per 1M tokens, taken from src/price/prices.json.
4	// A null price means "not confirmed", so a session that uses it has a null cost. We never guess.
5	
6	export type PriceRow = {
7	  id: string;
8	  model_pattern: string;
9	  input: number | null;
10	  output: number | null;
11	  cache_read: number | null;
12	  cache_write: number | null;
13	  cache_write_1h?: number | null;
14	  max_prompt_tokens?: number;
15	  min_prompt_tokens?: number;
16	  source_url: string | null;
17	  checked_on: string;
18	};
19	
20	export type TokenCounts = {
21	  /** Uncached input tokens. For OpenAI-style usage, subtract cached_input_tokens first. */
22	  input: number;
23	  /** Output tokens. For OpenAI-style usage, add reasoning_output_tokens (billed as output). */
24	  output: number;
25	  cache_read?: number;
26	  /** 5-minute cache writes. */
27	  cache_write?: number;
28	  /** 1-hour cache writes. Only priced where the row has cache_write_1h. */
29	  cache_write_1h?: number;
30	  /**
31	   * Total input of one request: input + cache_read + cache_write + cache_write_1h.
32	   * Tiered rows (Haiku 5.5 above 100k tokens) need it, so pass a single request's counts.
33	   * Sum the per-request results for a session.
34	   */
35	  prompt_tokens?: number;
36	  /**
37	   * Upper bound on any one request's prompt size, for when per-request sizes are not stored (a session's
38	   * total input is at least as large as any single request in it). Used only when it selects one tier;
39	   * otherwise the tier is ambiguous and the price is null.
40	   */
41	  prompt_tokens_bound?: number;
42	};
43	
44	export type PriceResult = {
45	  usd: number | null;
46	  row_id: string;
47	};
48	
49	const ROWS = rows.rows as PriceRow[];
50	
51	// Bedrock regional and multi-region endpoints cost 10% more than global ones
52	// (platform.claude.com/docs/en/about-claude/pricing, "Regional and multi-region endpoint pricing").
53	const REGIONAL_PREFIXES = new Set(["us", "eu", "jp", "au", "apac"]);
54	const REGIONAL_PREMIUM = 1.1;
55	
56	/**
57	 * Reduces a model id to its base name, e.g.
58	 *   "us.anthropic.claude-opus-5-5-v1:0" -> { base: "claude-opus-5-5", regional: true }
59	 *   "claude-opus-5-5[1m]"               -> { base: "claude-opus-5-5", regional: false }
60	 *   "global.anthropic.claude-haiku-5-5" -> { base: "claude-haiku-5-5", regional: false }
61	 *   "claude-sonnet-5-5-20260601"        -> { base: "claude-sonnet-5-5", regional: false }
62	 */
63	export function normaliseModelId(model: string): { base: string; regional: boolean } {
64	  let id = model.trim().toLowerCase();
65	  id = id.replace(/\[[^\]]*\]$/, "");
66	  let regional = false;
67	  for (;;) {
68	    const m = id.match(/^([a-z]+)\./);
69	    if (!m) break;
70	    const prefix = m[1] ?? "";
71	    if (prefix === "global") regional = false;
72	    else if (REGIONAL_PREFIXES.has(prefix)) regional = true;
73	    else if (prefix !== "anthropic") break;
74	    id = id.slice(m[0].length);
75	  }
76	  id = id.replace(/-v\d+(:\d+)?$/, "");
77	  id = id.replace(/-\d{8}$/, "").replace(/-\d{4}-\d{2}-\d{2}$/, "");
78	  return { base: id, regional };
79	}
80	
81	function pickRow(
82	  base: string,
83	  promptTokens: number | undefined,
84	  bound: number | undefined,
85	): PriceRow | "ambiguous" | undefined {
86	  const candidates = ROWS.filter((r) => r.model_pattern === base);
87	  if (candidates.length === 0) return undefined;
88	  if (candidates.length === 1) return candidates[0];
89	  if (promptTokens === undefined) {
90	    if (bound === undefined) return "ambiguous";
91	    // A row is reachable when its range starts at or below the bound. Only one reachable row is certain.
92	    const reachable = candidates.filter((r) => r.min_prompt_tokens === undefined || r.min_prompt_tokens <= bound);
93	    return reachable.length === 1 ? reachable[0] : "ambiguous";
94	  }
95	  return candidates.find(
96	    (r) =>
97	      (r.max_prompt_tokens === undefined || promptTokens <= r.max_prompt_tokens) &&
98	      (r.min_prompt_tokens === undefined || promptTokens >= r.min_prompt_tokens),
99	  );
100	}
101	
102	/** Prices one token-count record for a model. Returns usd: null when the model or price is unknown. */
103	export function priceSession(model: string, tokens: TokenCounts): PriceResult {
104	  const { base, regional } = normaliseModelId(model);
105	  const row = pickRow(base, tokens.prompt_tokens, tokens.prompt_tokens_bound);
106	  if (row === undefined) return { usd: null, row_id: "unknown" };
107	  if (row === "ambiguous") return { usd: null, row_id: "unknown" };
108	
109	  const counts: [number, number | null | undefined][] = [
110	    [tokens.input, row.input],
111	    [tokens.output, row.output],
112	    [tokens.cache_read ?? 0, row.cache_read],
113	    [tokens.cache_write ?? 0, row.cache_write],
114	    [tokens.cache_write_1h ?? 0, row.cache_write_1h],
115	  ];
116	  let usd = 0;
117	  for (const [count, price] of counts) {
118	    if (count === 0) continue;
119	    if (price === null || price === undefined) return { usd: null, row_id: row.id };
120	    usd += (count * price) / 1_000_000;
121	  }
122	  return { usd: regional ? usd * REGIONAL_PREMIUM : usd, row_id: row.id };
123	}
